/* Signature Balochi Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Mir Allahbakhsh": "From the title Mir (chief) + Allah Bakhsh ('God-given').", "Gulbibi": "From gul (flower) + bibi (lady): 'flower lady'.", "Dadshahgul": "From dad (justice) + shah (king) + gul.", "Chakarbeg": "From Chakar + beg (lord): 'lord Chakar'.", "Mahbibi": "From mah (moon) + bibi (lady): 'moon lady'.", "Shahdadgul": "From shah + dad + gul.", "Gulzai": "From gul + -zai (descendant of): Signature tribal-style surname.", "Mahzai": "From mah (moon) + -zai: Signature tribal-style surname.", "Dadzai": "From dad (justice) + -zai: Signature tribal-style surname.", "Shahwani": "Signature tribal-style surname in the -wani pattern."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Mir Allahbakhsh';
console.log(lookup(q));

